# Let me analyze what a "glowing game" transformation might look like
# Common patterns involve shapes expanding or duplicating

# If shapes "glow" by 1 pixel in all directions:
def glow_shape(shape, num_steps=1):
    """Expand a shape by num_steps in all directions"""
    if not shape:
        return shape
    rmin, rmax, cmin, cmax = shape_bbox(*shape)
    expanded = [[0]*(cmax+2*num_steps) for _ in range(rmax+2*num_steps+2)]
    for r in range(rmin, rmax+1):
        for c in range(cmin, cmax+1):
            if shape[r][c] != 0:
                value = shape[r][c]
                for dr in range(-num_steps, num_steps+1):
                    for dc in range(-num_steps, num_steps+1):
                        er, ec = r + dr + num_steps, c + dc + num_steps
                        expanded[er][ec] = value
    return expanded

def shape_bbox(shape):
    rows = len(shape)
    cols = len(shape[0])
    rmin, rmax = 0, rows-1
    cmin, cmax = 0, cols-1
    return (rmin, rmax, cmin, cmax)

